const characterImageViewer=document.createElement('dialog');
characterImageViewer.id='characterImageViewer';characterImageViewer.setAttribute('aria-labelledby','characterImageViewerTitle');
characterImageViewer.style.cssText='width:96vw;max-width:1600px;height:94vh;max-height:94vh;padding:16px;box-sizing:border-box';
characterImageViewer.innerHTML='<div class="modal-head"><h2 id="characterImageViewerTitle">人物原图</h2><button id="closeCharacterImageViewer" aria-label="关闭图片预览">✕</button></div><div style="height:calc(100% - 110px);overflow:auto;text-align:center;background:#080d14"><img id="characterImageViewerImage" alt="" style="width:100%;height:100%;object-fit:contain"></div><div style="display:flex;gap:16px;margin-top:14px;align-items:center"><a id="characterImageOriginal" target="_blank" rel="noopener" style="color:var(--green)">打开原图 ↗</a><a id="characterImageDownload" download style="color:var(--green)">下载原图</a></div>';
document.body.append(characterImageViewer);
document.querySelector('#closeCharacterImageViewer').onclick=()=>characterImageViewer.close();
characterImageViewer.addEventListener('click',e=>{if(e.target===characterImageViewer){const r=characterImageViewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)characterImageViewer.close()}});
function openCharacterImage(image){const url=new URL(image.currentSrc||image.src,location.href);if(url.origin!==location.origin||!/^\/api\/(front-image|contact-sheet)\//.test(url.pathname))return;const label=image.alt||image.closest('.angle')?.querySelector('span')?.textContent||'人物原图';document.querySelector('#characterImageViewerTitle').textContent=label;const full=document.querySelector('#characterImageViewerImage');full.src=url.href;full.alt=label;document.querySelector('#characterImageOriginal').href=url.href;const download=document.querySelector('#characterImageDownload');download.href=url.href;download.download=label+'.png';if(!characterImageViewer.open)characterImageViewer.showModal();}
document.addEventListener('click',e=>{const image=e.target.closest('#panel .angle-grid .angle img, #portraitCandidates img');if(image){e.preventDefault();openCharacterImage(image)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('#panel .angle-grid .angle img, #portraitCandidates img')){e.preventDefault();openCharacterImage(e.target)}});
const charactersBeforeImageViewer=characters;
characters=function(){charactersBeforeImageViewer();for(const image of document.querySelectorAll('#panel .angle-grid .angle img, #portraitCandidates img')){image.style.cursor='zoom-in';image.tabIndex=0;image.setAttribute('role','button');image.setAttribute('aria-label','放大查看 '+(image.alt||'人物图片'));image.title='点击查看原图';}};render();

(()=>{const full=document.querySelector('#characterImageViewerImage'),viewport=full.parentElement;let zoom=1;const controls=document.createElement('div');controls.style.cssText='display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:8px 0';controls.innerHTML='<button type="button" id="previewZoomOut" aria-label="缩小图片">−</button><span id="previewZoomLevel">100%</span><button type="button" id="previewZoomIn" aria-label="放大图片">＋</button><button type="button" id="previewZoomReset">适应窗口</button>';viewport.before(controls);viewport.style.height='calc(100% - 170px)';const original=document.querySelector('#characterImageOriginal');original.hidden=true;function update(){const fit=Math.min(viewport.clientWidth/full.naturalWidth,viewport.clientHeight/full.naturalHeight);if(!Number.isFinite(fit)||fit<=0)return;full.style.cssText='display:block;object-fit:contain;max-width:none;max-height:none;margin:auto;width:'+Math.round(full.naturalWidth*fit*zoom)+'px;height:'+Math.round(full.naturalHeight*fit*zoom)+'px';document.querySelector('#previewZoomLevel').textContent=Math.round(zoom*100)+'%';}full.addEventListener('load',()=>{zoom=1;update();});document.querySelector('#previewZoomOut').onclick=()=>{zoom=Math.max(0.5,zoom/1.25);update();};document.querySelector('#previewZoomIn').onclick=()=>{zoom=Math.min(6,zoom*1.25);update();};document.querySelector('#previewZoomReset').onclick=()=>{zoom=1;update();};const before=openCharacterImage;openCharacterImage=function(image){before(image);zoom=1;requestAnimationFrame(update);};})();

(()=>{const controls=document.createElement('div');controls.id='portraitPreviewNavigation';controls.style.cssText='display:flex;align-items:center;justify-content:center;gap:16px;margin:8px 0';controls.innerHTML='<button type="button" id="portraitPreviewPrevious" aria-label="上一张候选图">← 上一张</button><span id="portraitPreviewPosition"></span><button type="button" id="portraitPreviewNext" aria-label="下一张候选图">下一张 →</button>';document.querySelector('#characterImageViewerTitle').parentElement.after(controls);let images=[],index=0;function refresh(){controls.hidden=images.length<2;controls.style.display=images.length<2?'none':'flex';document.querySelector('#portraitPreviewPosition').textContent=(index+1)+' / '+images.length;}const prior=openCharacterImage;openCharacterImage=function(image){const group=image.closest('#portraitCandidates');images=group?[...group.querySelectorAll('img')]:[];index=Math.max(0,images.indexOf(image));prior(image);refresh();};function step(offset){if(images.length<2)return;index=(index+offset+images.length)%images.length;const image=images[index];prior(image);refresh();}document.querySelector('#portraitPreviewPrevious').onclick=()=>step(-1);document.querySelector('#portraitPreviewNext').onclick=()=>step(1);characterImageViewer.addEventListener('keydown',e=>{if(images.length<2||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowLeft'?-1:1);}});const viewport=document.querySelector('#characterImageViewerImage').parentElement;viewport.style.height='calc(100% - 225px)';controls.hidden=true;controls.style.display='none';})();
